describe('Homepage Hero Section Responsive Design', () => {
  beforeEach(() => {
    cy.visit('/');
  });

  it('should display hero section correctly on desktop viewport', () => {
    cy.viewport(1280, 720);

    cy.get('[data-testid="hero-section"]').should('be.visible');
    cy.get('[data-testid="hero-title"]').should('have.css', 'font-size').and('match', /^(4[0-8]|[5-9]\d)px$/);
    cy.get('[data-testid="hero-image"]').should('be.visible');
    cy.get('[data-testid="hero-cta-button"]').should('be.visible');

    cy.get('[data-testid="hero-section"]').should('have.css', 'display', 'flex');
    cy.get('[data-testid="hero-content"]').should('have.css', 'width').and('match', /^[5-9]\d%$/);
  });

  it('should display hero section correctly on mobile viewport', () => {
    cy.viewport(375, 667);

    cy.get('[data-testid="hero-section"]').should('be.visible');
    cy.get('[data-testid="hero-title"]').should('have.css', 'font-size').and('match', /^(2[0-4]|[1-2]\d)px$/);
    cy.get('[data-testid="hero-image"]').should('be.visible');
    cy.get('[data-testid="hero-cta-button"]').should('be.visible');

    cy.get('[data-testid="hero-section"]').should('have.css', 'flex-direction', 'column');
    cy.get('[data-testid="hero-content"]').should('have.css', 'width').and('match', /^100%$/);
  });

  it('should stack elements vertically on tablet viewport', () => {
    cy.viewport(768, 1024);

    cy.get('[data-testid="hero-section"]').should('be.visible');
    cy.get('[data-testid="hero-title"]').should('have.css', 'font-size').and('match', /^(3[0-6]|[2-3]\d)px$/);
    cy.get('[data-testid="hero-image"]').should('be.visible');

    cy.get('[data-testid="hero-section"]').should('have.css', 'flex-direction', 'column');
  });

  it('should handle missing hero image gracefully on mobile', () => {
    cy.viewport(375, 667);

    cy.get('[data-testid="hero-section"]').should('be.visible');
    cy.get('[data-testid="hero-title"]').should('be.visible').and('not.be.empty');
    cy.get('[data-testid="hero-cta-button"]').should('be.visible');

    cy.get('[data-testid="hero-image"]').then(($img) => {
      if ($img.length > 0) {
        cy.wrap($img).should('have.attr', 'src').and('not.be.empty');
      }
    });
  });

  it('should maintain proper spacing and padding on mobile', () => {
    cy.viewport(375, 667);

    cy.get('[data-testid="hero-section"]').should('have.css', 'padding').and('not.equal', '0px');
    cy.get('[data-testid="hero-content"]').should('have.css', 'padding').and('not.equal', '0px');

    cy.get('[data-testid="hero-section"]').invoke('height').should('be.greaterThan', 300);
  });
});
